157	/**
158	 * Combines multiple filter conditions using their associated logic operators (AND/OR).
159	 *
160	 * @param filterConditions - Array of conditions with their logic operators
161	 * @returns A single SQL fragment combining all conditions, or null if empty
162	 */
163	export function combineFilterConditions(
164	  filterConditions: FilterConditionWithOperator[],
165	): SQL<unknown> | null {
166	  if (filterConditions.length === 0) {
167	    return null;
168	  }
169	
170	  if (filterConditions.length === 1) {
171	    return filterConditions[0].condition;
172	  }
173	
174	  return filterConditions.reduce((acc, { condition: cond, logicOperator }, idx) => {
175	    if (idx === 0) {
176	      return cond;
177	    }
178	    return logicOperator === 'OR' ? sql`${acc} OR ${cond}` : sql`${acc} AND ${cond}`;
179	  }, filterConditions[0].condition);
180	}
