47	/**
48	 * Shallow-clone a test case so the caller can swap in resolved ApiProvider
49	 * instances on `options.provider` / `assert[].provider` without leaking those
50	 * mutations back to the input. The input may alias the unified config written
51	 * to the Eval record, and a live SDK client (e.g. Bedrock's BedrockRuntime,
52	 * Anthropic's client) holds circular references that break drizzle's JSON
53	 * serialization on `evalRecord.save()`. Fixes #8687.
54	 *
55	 * Detaches only `options` and `assert[]`. Other reference fields (`provider`,
56	 * `vars`, `metadata`, `providerOutput`) remain aliased — callers must reassign
57	 * those by reference rather than mutating in place. `assert-set` children are
58	 * not deep-cloned because the resolve loop skips `assert-set`; if that ever
59	 * changes, extend this helper.
60	 */
61	function cloneTestForResolve<T extends Pick<TestCase, 'options' | 'assert'>>(test: T): T {
62	  const cloned: T = { ...test };
63	  if (test.options) {
64	    cloned.options = { ...test.options };
65	  }
66	  if (test.assert) {
67	    cloned.assert = test.assert.map((assertion) => ({ ...assertion }));
68	  }
69	  return cloned;
70	}
